].forEach((timeZone) => {
  assert.throws(
    RangeError,
    () => instance.toZonedDateTime(timeZone),
    `ISO string ${timeZone} with a sub-minute offset is not a valid time zone`
  );
});

timeZone = "2021-08-19T17:30Z";
