  "hour": 24,
  "minute": 60,
  "second": 60,
  "millisecond": 1000,
  "microsecond": 1000,
  "nanosecond": 1000
};

Object.entries(nextIncrements).forEach(([unit, next]) => {
  assert.throws(
    RangeError,
    () => t.round({ smallestUnit: unit, roundingIncrement: next }),
    `throws on increments that are equal to the next highest (unit = ${unit}, increment = ${next})`
  );
});
