    -2, 0, 0, 0, 0, 0, 0, 0, 0, 0,
    `-2.5 years with ${mode} rounds toward zero`
  );
}
for (const mode of ["floor", "expand", "halfExpand", "halfFloor"]) {
  TemporalHelpers.assertDuration(
    earlier2.since(later, { smallestUnit: "years", roundingMode: mode }),
