function main(): void {
const other = new Temporal.ZonedDateTime(1_000_000_000_000_000_000n, "UTC");
const base = { year: 2000, month: 5, day: 2, hour: 15, minute: 30, second: 45, millisecond: 987, microsecond: 654, nanosecond: 321, timeZone: "UTC" };

